        {"reason": "Patching and backups are owned by different people, with no shared schedule listing both jobs' times."},
        {"reason": "Kernel updates require a restart because no live-patching was adopted, so auto-reboot was enabled as the default fix."}
      ]
    },
    {
      "reason": "The backup is scheduled through plain cron instead of anacron or a systemd timer with Persistent=true.",
      "whys": [
        {"reason": "The crontab entry was copied from an older always-on server where the host was never down at night."},
        {"reason": "Anacron only catches up jobs in /etc/cron.daily, and nobody realised a user crontab entry gets no catch-up."},
        {"reason": "Migrating to a systemd timer would change the script's environment and logging, so the working entry was left alone."}
      ]
    },
    {
      "reason": "The VM is suspended or powered off overnight by policies outside the backup job's control.",
      "whys": [
        {"reason": "An idle power policy suspends the VM when no sessions are active, and the backup takes no sleep inhibitor lock."},
        {"reason": "The cloud provider schedules host maintenance and live-migration pauses in early-morning hours matching the backup time."},
        {"reason": "A cost-saving auto-stop schedule was added to shut down low-traffic VMs overnight without checking scheduled jobs."}
      ]
    }
  ]
